action.code:
vec3 f = (center - eye).normalize();
vec3 s = f.cross(up).normalize();
vec3 u = s.cross(f);

mat4 view;
view << s.x, s.y, s.z, 0,
        u.x, u.y, u.z, 0,
        -f.x, -f.y, -f.z, 0,
        0, 0, 0, 1;

mat4 translate;
translate << 1, 0, 0, -eye.x,
           0, 1, 0, -eye.y,
           0, 0, 1, -eye.z,
           0, 0, 0, 1;

return view * translate;
// END_CODE

